python3 - <<'E'
p='config.go'
s=open(p).read()
s=s.replace('''	section, key, ok := strings.Cut(name, ".")
	if !ok {
		return c.Get("", name)
	}
	return c.Get(section, key)''','''	i := strings.LastIndex(name, ".")
	if i < 0 {
		return c.Get("", name)
	}
	return c.Get(name[:i], name[i+1:])''')
s=s.replace('// A name without a dot is a key in the unnamed section.','// The key is the part after the last dot, so section names may contain dots.\n// A name without a dot is a key in the unnamed section.')
open(p,'w').write(s)
p='cmd/kvconf/main.go'
s=open(p).read()
s=s.replace('''		section, key := splitName(args[2])
		v, err := cfg.Get(section, key)''','''		v, err := cfg.Lookup(args[2])''')
i=s.index('// splitName')
s=s[:i].rstrip()+'\n'
s=s.replace('\t"strings"\n','')
open(p,'w').write(s)
E
cat >> cmd/kvconf/main_test.go <<'E'

func TestGetDottedSection(t *testing.T) {
	var out, errb bytes.Buffer
	if code := run([]string{"get", "../../checks/dotted.conf", "db.eu.host"}, &out, &errb); code != 0 {
		t.Fatalf("exit %d: %s", code, errb.String())
	}
	if out.String() != "db1.example.org\n" {
		t.Errorf("got %q", out.String())
	}
}
E
gofmt -l .; go vet ./... && interlock check run --criterion repro; interlock check run --criterion regression

